import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1787002545000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>All configuration is by environment variable; there is no config file.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>LINKWARDEN_URL</code></td><td>yes</td><td>string</td><td>—</td><td>Base URL, e.g. <code>https://links.example.net</code>. Without <code>/api/v1</code>.</td></tr><tr><td><code>LINKWARDEN_TOKEN</code></td><td>yes</td><td>secret</td><td>—</td><td>Access token from Settings → Access Tokens.</td></tr><tr><td><code>LINKWARDEN_READ_ONLY</code></td><td>no</td><td>boolean</td><td><code>false</code></td><td><code>true</code> registers only the 11 read tools.</td></tr><tr><td><code>LINKWARDEN_INSECURE_TLS</code></td><td>no</td><td>boolean</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to this connection.</td></tr></tbody></table><p>Booleans are compared against the literal string <code>true</code>. <code>True</code>, <code>1</code> and <code>yes</code> are off, so a typo fails closed rather than silently disabling certificate validation.</p><h2 id="validation-at-startup" tabindex="-1">Validation at startup <a class="header-anchor" href="#validation-at-startup" aria-label="Permalink to “Validation at startup”">​</a></h2><p><code>LINKWARDEN_URL</code> is parsed with <code>new URL</code>. The server <strong>exits</strong> when it:</p><ul><li>does not parse,</li><li>uses a scheme other than <code>http:</code> or <code>https:</code>,</li><li>contains credentials (<code>https://user:pw@host</code>).</li></ul><p>It <strong>warns and continues</strong> when:</p><ul><li>the URL is plain <code>http:</code> to a non-loopback host (the token would be sent in clear),</li><li><code>LINKWARDEN_TOKEN</code> does not start with <code>ey</code> (Linkwarden tokens are NextAuth JWTs, so this usually means a cookie or password was pasted in),</li><li>either required variable is missing — the server still starts and lists its tools so registries and inspectors can introspect it; every call then fails with setup instructions.</li></ul><p>Normalisation: a trailing slash is stripped, and a <code>/api/v1</code> suffix is removed, since the client appends the prefix itself and redirects are never followed.</p><h2 id="token-handling" tabindex="-1">Token handling <a class="header-anchor" href="#token-handling" aria-label="Permalink to “Token handling”">​</a></h2><p><code>LINKWARDEN_TOKEN</code> is <strong>deleted from the process environment</strong> as soon as it is read — before any branch of the parser, including the ones that exit — so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>. It is never logged and never appears in an error message.</p><h2 id="not-environment-variables" tabindex="-1">Not environment variables <a class="header-anchor" href="#not-environment-variables" aria-label="Permalink to “Not environment variables”">​</a></h2><p>There are no variables for timeouts, page sizes or result budgets; those are fixed:</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>30 s</td></tr><tr><td>Response body ceiling</td><td>8 MB</td></tr><tr><td>Result budget</td><td>200 000 characters</td></tr><tr><td>Links per search</td><td>100</td></tr><tr><td>Links per bulk operation</td><td>200</td></tr><tr><td>Article slice, default</td><td>20 000 characters</td></tr><tr><td>Confirmation token TTL</td><td>5 minutes</td></tr></tbody></table>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};